statement:
`grid` is a rectangular map given as an array of equal-length strings. Each cell is one of:

- `'.'`: open floor;
- `'#'`: a wall that can never be entered;
- `'@'`: your starting cell (there is exactly one);
- a lowercase letter: a key, which you collect the moment you step onto its cell;
- an uppercase letter: a lock, which you may step onto only while you already hold the key with the same letter in lowercase.

For some `k` between 1 and 6, the keys are exactly the first `k` letters of the alphabet, each appearing once, and each has exactly one lock of the matching uppercase letter. A move takes you one cell up, down, left or right, never off the grid. Return the smallest number of moves after which you hold all `k` keys (locks do not have to be opened), or `-1` if that can never happen.

validator:
function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 30) return 'grid needs 1 to 30 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 30) return 'Each row needs 1 to 30 cells.';
  let starts = 0;
  const keys = new Map();
  const locks = new Map();
  for (const row of grid) {
    if (typeof row !== 'string' || row.length !== cols) return 'All rows must have the same length.';
    for (const ch of row) {
      if (ch === '@') starts++;
      else if (ch >= 'a' && ch <= 'z') keys.set(ch, (keys.get(ch) || 0) + 1);
      else if (ch >= 'A' && ch <= 'Z') locks.set(ch, (locks.get(ch) || 0) + 1);
      else if (ch !== '.' && ch !== '#') return 'Cells are letters, ".", "#" or "@".';
    }
  }
  if (starts !== 1) return 'The grid needs exactly one "@".';
  const k = keys.size;
  if (k < 1 || k > 6) return 'The grid needs 1 to 6 keys.';
  if (locks.size !== k) return 'Every key needs exactly one matching lock.';
  for (let i = 0; i < k; i++) {
    const key = String.fromCharCode(97 + i);
    const lock = String.fromCharCode(65 + i);
    if (keys.get(key) !== 1 || locks.get(lock) !== 1) return 'Keys and locks must be the first k letters, each appearing once.';
  }
  return null;
}

