function shortestPathAllKeys(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let startRow = 0;
  let startCol = 0;
  let keyCount = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const cell = grid[r][c];
      if (cell === '@') {
        startRow = r;
        startCol = c;
      } else if (cell >= 'a' && cell <= 'z') {
        keyCount++;
      }
    }
  }
  const allKeys = (1 << keyCount) - 1;
  const visited = new Uint8Array(rows * cols * 64);
  visited[(startRow * cols + startCol) * 64] = 1;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let queue = [[startRow, startCol, 0]];
  let steps = 0;

  while (queue.length > 0) {
    const next = [];
    for (const [row, col, keys] of queue) {
      if (keys === allKeys) return steps;
      for (const [dr, dc] of directions) {
        const r = row + dr;
        const c = col + dc;
        if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
        const cell = grid[r][c];
        if (cell === '#') continue;
        if (cell >= 'A' && cell <= 'Z' && !(keys & (1 << (cell.charCodeAt(0) - 65)))) continue;
        let newKeys = keys;
        if (cell >= 'a' && cell <= 'z') newKeys |= 1 << (cell.charCodeAt(0) - 97);
        const id = (r * cols + c) * 64 + newKeys;
        if (visited[id]) continue;
        visited[id] = 1;
        next.push([r, c, newKeys]);
      }
    }
    queue = next;
    steps++;
  }
  return -1;
}

