function shortestPathAllKeys(grid) {
  // Try every order of first visits; each leg is a plain BFS using only the keys already held.
  const rows = grid.length, cols = grid[0].length;
  const where = {};
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const ch = grid[r][c];
    if (ch === '@' || (ch >= 'a' && ch <= 'z')) where[ch] = [r, c];
  }
  const keys = Object.keys(where).filter(ch => ch !== '@');
  const leg = (from, to, held) => {
    const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));
    dist[from[0]][from[1]] = 0;
    const q = [from];
    for (let h = 0; h < q.length; h++) {
      const [r, c] = q[h];
      if (r === to[0] && c === to[1]) return dist[r][c];
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || dist[nr][nc] !== -1) continue;
        const ch = grid[nr][nc];
        if (ch === '#') continue;
        if (ch >= 'A' && ch <= 'Z' && !held.has(ch.toLowerCase())) continue;
        dist[nr][nc] = dist[r][c] + 1;
        q.push([nr, nc]);
      }
    }
    return -1;
  };
  let best = -1;
  const order = [];
  const used = new Set();
  const walk = (cur, total) => {
    if (order.length === keys.length) {
      if (best === -1 || total < best) best = total;
      return;
    }
    for (const k of keys) {
      if (used.has(k)) continue;
      const d = leg(cur, where[k], used);
      if (d === -1) continue;
      used.add(k); order.push(k);
      walk(where[k], total + d);
      used.delete(k); order.pop();
    }
  };
  walk(where['@'], 0);
  return best;
}

