function generate(rand, size) {
  const large = size === 'large';
  for (;;) {
    const rows = large ? 30 : 1 + Math.floor(rand() * 5);
    const cols = large ? 30 : 1 + Math.floor(rand() * 5);
    const cells = rows * cols;
    if (cells < 3) continue;
    const k = large ? 6 : 1 + Math.floor(rand() * Math.min(4, Math.floor((cells - 1) / 2)));
    const wallRate = large ? 0.15 + rand() * 0.15 : rand() * 0.35;
    const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < wallRate ? '#' : '.')));
    const order = Array.from({ length: cells }, (_, i) => i);
    for (let i = cells - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
    const put = (idx, ch) => { grid[Math.floor(order[idx] / cols)][order[idx] % cols] = ch; };
    put(0, '@');
    for (let i = 0; i < k; i++) {
      put(1 + 2 * i, String.fromCharCode(97 + i));
      put(2 + 2 * i, String.fromCharCode(65 + i));
    }
    return [grid.map(row => row.join(''))];
  }
}
